/**
 * Add-to-glasses landing page.
 *
 * Mobile (iPhone/Android): shows a giant tap-to-add button that fires
 * the `fb-viewapp://` deep link directly. Meta AI app opens with the
 * "Add a web app" sheet pre-filled with the game URL.
 *
 * Desktop: shows a static QR code (PNG generated by build-qr.py) that
 * encodes the URL of THIS page. When the user's phone scans the QR,
 * they land on this same page in mobile mode and the tap button does
 * the rest. We deliberately encode the https URL of the add page, not
 * the fb-viewapp:// deep link, because phone QR scanners reliably
 * follow https URLs but may block custom URL schemes.
 */

import { findByCode, findById, fullUrl, deepLink, isMobileBrowser } from '../manifest.js';

const params = new URLSearchParams(location.search);
const code = params.get('code');
const id = params.get('game');
const game = code ? findByCode(code) : id ? findById(id) : null;

const content = document.getElementById('content');

if (!game) {
  content.innerHTML = `
    <div class="error-state">
      <h1>Couldn't find that game</h1>
      <p>${code ? `No game registered for code <strong>${code}</strong>.` : 'Missing game code.'}</p>
      <a href="../">Back to catalog</a>
    </div>
  `;
} else {
  const url = fullUrl(game);
  const link = deepLink(game);
  const mobile = isMobileBrowser();
  // QR is pre-generated per game code by tools/build-qr.py and committed to
  // webapp/add/qr-<code>.png. The PNG encodes the add-page URL so phone
  // scanners land here in mobile mode and get the tap button.
  const qrSrc = `qr-${game.shareCode}.png`;

  content.innerHTML = `
    <a class="back" href="../">◄ All games</a>
    <div class="game-header">
      <span class="glyph">${game.emoji}</span>
      <h1>${game.name}</h1>
    </div>
    <p class="blurb">${game.blurb}</p>
    <div class="share-code">SHARE CODE · ${game.shareCode}</div>

    <div class="add-card">
      ${
        mobile
          ? `
        <a id="add-btn" class="mobile-add-btn" href="${link}">ADD TO GLASSES</a>
        <p class="mobile-sub">
          Tapping opens the <strong>Meta AI app</strong> with this game pre-filled.<br/>
          Confirm "Add" and it shows up on your Display glasses.
        </p>
      `
          : `
        <div class="desktop-qr">
          <div class="qr-frame">
            <img src="${qrSrc}" width="260" height="260" alt="QR code to add ${game.name} to your glasses" />
          </div>
          <p>Open your iPhone camera and point it at this code — <span>your phone</span> will get the Add-to-Glasses tap button.</p>
        </div>
      `
      }
    </div>

    <div class="manual">
      <h3>Or add it manually</h3>
      <p>
        Open the <strong>Meta AI app</strong> on your paired phone →
        <strong>Devices</strong> → <strong>Display Glasses settings</strong> →
        <strong>App connections</strong> → <strong>Web apps</strong> →
        <strong>Add a web app</strong>. Name it <em>${game.name}</em> and paste:
      </p>
      <div class="url-row">
        <code id="raw-url">${url}</code>
        <button id="copy-btn" class="copy-btn">COPY</button>
      </div>
    </div>

    <a class="play-link" href="${game.path}">► Play in this browser (preview only — for real play, add to glasses)</a>
  `;

  // Copy URL button
  const copyBtn = document.getElementById('copy-btn');
  copyBtn.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(url);
      copyBtn.textContent = 'COPIED';
      copyBtn.classList.add('copied');
      setTimeout(() => {
        copyBtn.textContent = 'COPY';
        copyBtn.classList.remove('copied');
      }, 1600);
    } catch (e) {
      const range = document.createRange();
      range.selectNode(document.getElementById('raw-url'));
      window.getSelection().removeAllRanges();
      window.getSelection().addRange(range);
    }
  });
}
